using System;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using IdleIntelligence.Core;
using UnityEngine;
using UnityEngine.UI;
namespace IdleIntelligence.Runtime
{
 public sealed class GemFeatureView:MonoBehaviour
 {
  GameRuntime game;Transform content;Text header,notice;Button draw,video;string page="permanent",signature="",transaction="";CancellationTokenSource cancellation;readonly IRewardedVideoProvider provider=new UnavailableRewardedVideoProvider();readonly List<Action> refresh=new List<Action>();
  public void Initialize(GameRuntime runtime){game=runtime;ItemPortrait.Sprites=game.WorkshopPrefab.ItemSprites;header=WorkshopUIFactory.Label("GemHeader",transform,"",16,72);var nav=WorkshopUIFactory.Horizontal("GemNavigation",transform).transform;foreach(string section in new[]{"permanent","time","materials","capsule"}){string id=section;WorkshopUIFactory.Button("GemPage-"+id,nav,id=="permanent"?"Upgrades":id=="time"?"Zeit":id=="materials"?"Material":"Gumball",()=>{page=id;Build();Canvas.ForceUpdateCanvases();game.Content.GetComponentInParent<ScrollRect>().verticalNormalizedPosition=1;});}notice=WorkshopUIFactory.Label("GemNotice",transform,"Transaktionen werden vor der Ergebnisanzeige gespeichert.",14,64);content=WorkshopUIFactory.Vertical("GemContent",transform).transform;Build();}
  string Signature()=>page+":"+game.State.Upgrades.processed.Length+":"+game.State.Capsules.draws+":"+game.State.Capsules.hasRequest;
  void Update(){if(game==null)return;if(signature!=Signature())Build();var s=game.State;header.text=s.Retention.gems+" GEMS\n"+PrestigeAutomation.LabCount(s)+" Labore · Offline "+Math.Round(Game.OfflineLimit(s)/3600,2)+" h\nLaborbonus: "+Math.Ceiling(Math.Max(0,s.Upgrades.labBoostUntil-s.SavedAt)/1000)+" s";foreach(var action in refresh)action();if(draw!=null){var q=Capsules.Quote(s);draw.interactable=game.Writable&&q.Allowed;draw.GetComponentInChildren<Text>().text=q.Reason=="prestige"?"Ab erstem Prestige":q.Reason=="challenge"?"Im Hauptspiel verfügbar":"Ziehen · "+GemBalance.CapsuleCost+" Gems";video.interactable=game.Writable&&q.VideoAllowed&&transaction==""&&!s.Capsules.hasRequest;video.GetComponentInChildren<Text>().text="Video · "+q.VideoRemaining+" / "+GemBalance.CapsuleVideoLimit+(PurchaseRules.AdFree(s)?" · ohne Video":" · nicht verfügbar");}}
  ActionCard Card(string name,string title){var c=Instantiate(game.CardPrefab,content);c.name=name;c.Title.text=title;c.Title.fontSize=16;c.Detail.fontSize=14;c.Icon.gameObject.SetActive(false);c.GetComponent<LayoutElement>().preferredHeight=200;return c;}
  static string Reason(string code)=>code==null?"Verfügbar":code=="owned"?"Bereits erworben":code=="previous"?"Vorherige Stufe erforderlich":code=="prestige-lab"?"INT-Knoten F01 erforderlich":code=="locked-materials"?"Materialzugang fehlt":code=="no-training"?"Kein aktives Training":code=="no-crafting"?"Kein aktiver Modulauftrag":code=="cap"?"Bonuslimit erreicht":code=="gems"?"Gems fehlen":code=="challenge"?"Hauptspiel pausiert":code;
  void Build(){signature=Signature();WorkshopUIFactory.Clear(content);refresh.Clear();draw=video=null;var s=game.State;
   if(page!="capsule"){foreach(var offer in GemBalance.Offers.Where(o=>o.Section==page)){string id=offer.Id;int expected=s.Upgrades.processed.Length;var card=Card("GemOffer-"+id,offer.Name);card.Button.onClick.AddListener(()=>{bool ok=game.Act(v=>v.Upgrades.processed.Length==expected?GemShop.Buy(v,id):v);notice.text=ok?"Kauf und Wirkung gespeichert.":"Kein weiterer Kauf. Angebot und Bestand prüfen.";});refresh.Add(()=>{var q=GemShop.Quote(game.State,id);card.Detail.text=offer.Effect+"\n"+q.Cost+" Gems · "+Reason(q.Reason)+(q.HasTime?"\nRest "+Math.Ceiling(q.Remaining)+" s · Verkürzung "+Math.Ceiling(q.Applied)+" s":"");card.Button.interactable=game.Writable&&q.Enabled;});}return;}
   long next=Capsules.Quote(s).Next;draw=WorkshopUIFactory.Button("CapsuleDraw",content,"Ziehen",()=>{bool ok=game.Act(v=>Capsules.Draw(v,next));notice.text=ok?"Ergebnis gespeichert.":"Keine weitere Ziehung. Bestand und Freischaltung prüfen.";});video=WorkshopUIFactory.Button("CapsuleVideo",content,"Video nicht verfügbar",RequestVideo);
   if(s.Capsules.hasRequest){string tx=s.Capsules.request.id;WorkshopUIFactory.Button("CapsuleCancel",content,"Offenen Videoauftrag abbrechen",()=>game.Act(v=>Capsules.CancelVideo(v,tx)));}
   WorkshopUIFactory.Label("CapsuleOdds",content,"Item "+(GemBalance.ItemChance*100)+" % · Komponenten "+(GemBalance.ComponentChance*100)+" %\nCredits "+(GemBalance.CreditChance*100)+" % · Daten "+(GemBalance.DataChance*100)+" %\nGems "+(GemBalance.GemChance*100)+" % · Jackpot "+(GemBalance.JackpotChance*100)+" %\nItems: gewöhnlich, aus dem zugänglichen Pool.\nCredits/Daten: "+GemBalance.CreditSeconds[0]+"–"+GemBalance.CreditSeconds[1]+" Produktionssekunden (mind. "+GemBalance.CreditFloor+" / "+GemBalance.DataFloor+").\nGems: "+GemBalance.GemRange[0]+"–"+GemBalance.GemRange[1]+" · Jackpot: "+(GemBalance.CapsuleCost*GemBalance.JackpotMultiplier)+" Gems",14,200);
   if(!s.Capsules.hasLast)return;var r=s.Capsules.last;var receipt=Card("CapsuleReceipt","Ergebnis #"+r.id+" · "+r.payment);receipt.transform.SetSiblingIndex(0);receipt.GetComponent<LayoutElement>().preferredHeight=120;receipt.Button.interactable=false;receipt.Detail.text=r.kind=="item"?ItemBalance.Items[Workshop.Index(r.itemType)].Name+"\n"+ItemBalance.Rarities[r.rarity]:r.kind=="components"?string.Join("\n",r.components.Select((n,i)=>n>0?ItemBalance.ComponentNames[i]+" × "+n:"").Where(t=>t!="")):r.resourceId+" + "+ScientificNumber.FromData(r.amount).ToString();
   if(r.kind=="item"){receipt.Icon.gameObject.SetActive(true);receipt.Icon.color=Color.clear;var p=Instantiate(game.WorkshopPrefab.PortraitPrefab,receipt.Icon.transform);var rect=(RectTransform)p.transform;rect.anchorMin=rect.anchorMax=new Vector2(.5f,.5f);rect.sizeDelta=new Vector2(58,58);rect.anchoredPosition=Vector2.zero;p.Bind(new ItemInstance{type=r.itemType,rarity=r.rarity});p.Caption.text="";p.Button.interactable=false;p.Button.targetGraphic.raycastTarget=false;}else if(r.kind=="components"){receipt.Icon.gameObject.SetActive(true);receipt.Icon.sprite=game.WorkshopPrefab.ComponentSprites[Array.FindIndex(r.components,n=>n>0)];receipt.Icon.preserveAspect=true;}
  }
  async void RequestVideo(){if(transaction!=""||!Capsules.Quote(game.State).VideoAllowed)return;if(!game.AcquireRewardRequest())return;string tx="capsule-video-"+Guid.NewGuid().ToString("N");if(!game.Act(s=>Capsules.BeginVideo(s,tx)))return;if(PurchaseRules.AdFree(game.State)){game.Act(s=>Capsules.ClaimAdFree(s,tx));notice.text="Werbefrei-Anspruch gespeichert. Keine Anzeige abgespielt.";return;}transaction=tx;cancellation=new CancellationTokenSource();RewardProviderResult result;try{result=await provider.ShowAsync("capsule",tx,cancellation.Token);}catch(OperationCanceledException){result=RewardProviderResult.Cancelled;}catch{result=RewardProviderResult.Failed;}if(game!=null)game.Act(s=>Capsules.CompleteRequestedVideo(s,tx,result.ToString().ToLowerInvariant()));if(this!=null){transaction="";notice.text=result==RewardProviderResult.Unavailable?"Keine Werbequelle. Keine Belohnung und kein Limit verbucht.":"Videoauftrag beendet.";cancellation?.Dispose();cancellation=null;}}
  void OnDisable(){cancellation?.Cancel();if(game!=null&&transaction!="")game.Act(s=>Capsules.CancelVideo(s,transaction));}
 }
}
